--  PluX Hub - KEY SYSTEM (jalan dulu sebelum hub dimuat)
--========================================================--
do
    local Players          = game:GetService("Players")
        local RunService       = game:GetService("RunService")
            local TweenService     = game:GetService("TweenService")
                local HttpService      = game:GetService("HttpService")
                    local Lighting         = game:GetService("Lighting")
                        local CoreGui          = game:GetService("CoreGui")

                            ------------------------------------------------------------
                                -- KONFIGURASI (ganti sesuai web key kamu)
                                    ------------------------------------------------------------
                                        local JUNKIE_SERVICE    = "PluX Hub"        -- nama service, harus persis seperti di dashboard
                                            local JUNKIE_IDENTIFIER = "1223099"         -- << CEK: user ID Junkie kamu
                                                local JUNKIE_PROVIDER   = "GANTI-PROVIDER"  -- << ISI: nama provider (menu Providers di dashboard)
                                                    local KEY_FILE      = "PluX/key.txt"
                                                        ------------------------------------------------------------

                                                            local function GetContainer()
                                                                    if gethui then
                                                                                local ok, hui = pcall(gethui)
                                                                                            if ok and hui then return hui end
                                                                                                    end
                                                                                                            return CoreGui
                                                                                                                end
                                                                                                                    local Container = GetContainer()
                                                                                                                        pcall(function()
                                                                                                                                local old = Container:FindFirstChild("PluXKey")
                                                                                                                                        if old then old:Destroy() end
                                                                                                                                            end)

                                                                                                                                                -- ===== file helper =====
                                                                                                                                                    local function SaveKey(k)
                                                                                                                                                            pcall(function()
                                                                                                                                                                        if writefile then
                                                                                                                                                                                        if makefolder and isfolder and not isfolder("PluX") then makefolder("PluX") end
                                                                                                                                                                                                        writefile(KEY_FILE, k)
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                            end)
                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                    local function LoadKey()
                                                                                                                                                                                                                                            local k
                                                                                                                                                                                                                                                    pcall(function()
                                                                                                                                                                                                                                                                if readfile and isfile and isfile(KEY_FILE) then k = readfile(KEY_FILE) end
                                                                                                                                                                                                                                                                        end)
                                                                                                                                                                                                                                                                                return k and k:gsub("%s+", "") or nil
                                                                                                                                                                                                                                                                                    end
                                                                                                                                                                                                                                                                                        local function DeleteKey()
                                                                                                                                                                                                                                                                                                pcall(function()
                                                                                                                                                                                                                                                                                                            if delfile and isfile and isfile(KEY_FILE) then delfile(KEY_FILE)
                                                                                                                                                                                                                                                                                                                        elseif writefile then writefile(KEY_FILE, "") end
                                                                                                                                                                                                                                                                                                                                end)
                                                                                                                                                                                                                                                                                                                                    end

                                                                                                                                                                                                                                                                                                                                        -- ===== Junkie SDK =====
                                                                                                                                                                                                                                                                                                                                            local Junkie
                                                                                                                                                                                                                                                                                                                                                local function GetJunkie()
                                                                                                                                                                                                                                                                                                                                                        if Junkie then return Junkie end
                                                                                                                                                                                                                                                                                                                                                                local ok, lib = pcall(function()
                                                                                                                                                                                                                                                                                                                                                                            return loadstring(game:HttpGet("https://jnkie.com/sdk/library.lua"))()
                                                                                                                                                                                                                                                                                                                                                                                    end)
                                                                                                                                                                                                                                                                                                                                                                                            if ok and type(lib) == "table" then
                                                                                                                                                                                                                                                                                                                                                                                                        lib.service = JUNKIE_SERVICE
                                                                                                                                                                                                                                                                                                                                                                                                                    lib.identifier = tostring(JUNKIE_IDENTIFIER)
                                                                                                                                                                                                                                                                                                                                                                                                                                if not JUNKIE_PROVIDER:find("GANTI%-PROVIDER") then
                                                                                                                                                                                                                                                                                                                                                                                                                                                lib.provider = JUNKIE_PROVIDER
                                                                                                                                                                                                                                                                                                                                                                                                                                                            end
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Junkie = lib
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return Junkie
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            end

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                -- return: "valid" | "invalid" | "error", pesan
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    local function CheckKey(key)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            local J = GetJunkie()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if not J then return "error", "Gagal load Junkie SDK" end
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            local ok, result = pcall(J.check_key, key)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if not ok then return "error", "Gagal cek key" end
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if type(result) == "table" then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if result.valid then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        getgenv().SCRIPT_KEY = key
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return "valid"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    end
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                local code = tostring(result.error or result.code or result.status or ""):upper()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if code:find("SERVICE_NOT_FOUND") then return "error", "Service tidak ditemukan (cek nama service)" end
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if code:find("SERVICE_MISMATCH") then return "invalid", "Key ini untuk service lain" end
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return "invalid", type(result.message) == "string" and result.message or nil
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            end
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return "invalid"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        end

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            -- ===== cek key tersimpan (tanpa GUI) =====
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                local verified = false
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    local saved = LoadKey()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if saved and #saved > 0 then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if CheckKey(saved) == "valid" then verified = true end
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    end
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if not verified then -- kalau key tersimpan belum valid, tampilkan GUI

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            -- ===== blur + overlay abu-abu =====
